package com.yuegang.zhihui.product.api;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.web.*;import com.yuegang.zhihui.product.application.*;import com.yuegang.zhihui.product.security.*;import jakarta.servlet.http.*;import jakarta.validation.Valid;import java.util.List;import org.springframework.web.bind.annotation.*;@RestController public final class ProductController{private final ProductService service;private final ProductAdminVerifier admin;public ProductController(ProductService s,ProductAdminVerifier a){service=s;admin=a;}@GetMapping("/api/v1/products")ApiResponse<List<ProductView>>list(@RequestParam(required=false)String category,@RequestParam(required=false)String keyword,@RequestParam(defaultValue="20")int limit,HttpServletRequest r){return ok(service.list(category,keyword,limit,true),r);}@GetMapping("/api/v1/products/{sku}")ApiResponse<ProductView>get(@PathVariable String sku,HttpServletRequest r){return ok(service.get(sku,true),r);}@PostMapping("/api/v1/admin/products")ApiResponse<ProductView>create(@Valid @RequestBody SaveProductRequest c,HttpServletRequest r){admin.verify(r);return ok(service.create(c),r);}@GetMapping("/api/v1/admin/products")ApiResponse<List<ProductView>>adminList(@RequestParam(required=false)String category,@RequestParam(required=false)String keyword,@RequestParam(defaultValue="50")int limit,HttpServletRequest r){admin.verify(r);return ok(service.list(category,keyword,limit,false),r);}@PutMapping("/api/v1/admin/products/{sku}/status")ApiResponse<ProductView>status(@PathVariable String sku,@RequestParam ProductStatus status,@RequestParam long version,HttpServletRequest r){admin.verify(r);return ok(service.changeStatus(sku,status,version),r);}private static<T>ApiResponse<T>ok(T d,HttpServletRequest r){return ApiResponse.success(d,TraceIdResolver.resolve(r));}}
